{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are we minimizing the number of containers used, maximizing the total weight (or total units) of goods shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped, or is it acceptable to leave some units of any type unshipped (i.e., the per-type totals are upper bounds, not requirements)?"
  ],
  "rationale": "The response asks a single clarification question regarding whether shipment quantities are mandatory or optional, presented as a binary choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited (we can use as many as needed), or is there a fixed fleet size that we must choose from?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability of containers, presenting a binary choice between unlimited and fixed fleet size."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units indivisible (each unit must be whole, so container loads are integer numbers of units per type), or can units be split fractionally?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The 18-ton minimum applies to every container that is used — is that correct, meaning a container can only be opened if its total load is at least 18 tons (and at most 60 tons)?"
  ],
  "rationale": "The response asks for confirmation of a single policy constraint regarding container load limits, which constitutes one semantically independent clarification question."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "does this apply to every used container",
    "is it one-way only (C without A is fine)"
  ],
  "rationale": "The response asks two distinct clarifications: the scope of the rule (every used container) and the directionality of the constraint (one-way only). These can be answered independently."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The \"at least 12 units of type D\" requirement — does it apply to every used container, or only to containers that contain any type D at all?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy scope choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is it acceptable for the plan to ship only a subset of the goods (leaving the rest unshipped) in order to minimize the number of containers, or is there a requirement to ship as much as possible?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether partial shipping is allowed or if maximum shipping is required."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is that acceptable, or is there a minimum amount of goods that must be shipped?"
  ],
  "rationale": "The response asks for a single policy decision regarding whether zero shipment is allowed or if a minimum quantity is required."
}

{
  "action": "question",
  "question_count": 1,
